async function supply(){head('Tanken / Versorgung',S.vehicle.name);app.innerHTML='<div class="card">Komponenten werden geladen …</div>';try{const api=await getCloud(),cs=(await list(api,'Komponenten')).filter(x=>String(x.fields.FahrzeugId)===String(S.vehicle.id)&&x.fields.Aktiv!==false);app.innerHTML=`<div class="card"><div class="field"><label>Komponente / Tank</label><select id="suComp"><option value="">– Fahrzeug allgemein –</option>${cs.map(x=>`<option value="${x.id}">${esc(x.fields.Name)} · ${esc(x.fields.KomponentenTyp||'')}</option>`).join('')}</select></div><div class="grid compact"><input id="suType" placeholder="Art, z. B. Diesel / Wasser / Strom"><input id="suAmount" type="number" step="0.01" placeholder="Menge"><input id="suUnit" placeholder="Einheit, z. B. l / kWh"><input id="suCost" type="number" step="0.01" placeholder="Kosten"><input id="suCur" value="EUR"></div><button class="primary" onclick="saveSupply()">Speichern</button></div>`}catch(e){failBox(e)}}
