async function measure(){head('Messwert / Füllstand',S.vehicle.name);app.innerHTML='<div class="card">Komponenten werden geladen …</div>';try{const api=await getCloud(),cs=(await list(api,'Komponenten')).filter(x=>String(x.fields.FahrzeugId)===String(S.vehicle.id)&&x.fields.Aktiv!==false);app.innerHTML=`<div class="card"><select id="meComp"><option value="">– Fahrzeug –</option>${cs.map(x=>`<option value="${x.id}">${esc(x.fields.Name)}</option>`).join('')}</select><div class="grid compact"><input id="meName" placeholder="Messgröße"><input id="meVal" type="number" step="0.01" placeholder="Wert"><input id="meUnit" placeholder="Einheit"></div><button class="primary" onclick="saveMeasure()">Speichern</button></div>`}catch(e){failBox(e)}}
async function saveMeasure(){if(!meName.value.trim()||!meVal.value)return alert('Messgröße und Wert eingeben.');try{const api=await getCloud();await api.createItemByName('Messwerte',{FahrzeugId:String(S.vehicle.id),NutzungId:String(S.usage.cloudId),TagesetappeId:String(S.day.id),KomponenteId:meComp.value||'',Messgroesse:meName.value.trim(),Wert:Number(meVal.value),Einheit:meUnit.value.trim(),Phase:'Zwischenwert',GemessenAm:new Date().toISOString(),Quelle:'Manuell',Testdaten:testFlag(),Aktiv:true});back()}catch(e){alert(e.message)}}
function gps(){head('GPS-Punkt',S.vehicle.name);app.innerHTML=`<div class="card"><button class="primary" onclick="captureGps()">Aktuelle Position übernehmen</button><div class="grid compact"><input id="gpLat" type="number" step="0.000001" placeholder="Breitengrad"><input id="gpLon" type="number" step="0.000001" placeholder="Längengrad"></div><button onclick="saveGps()">GPS-Punkt speichern</button></div>`}
function captureGps(){if(!navigator.geolocation)return alert('GPS wird von diesem Browser nicht unterstützt.');navigator.geolocation.getCurrentPosition(p=>{gpLat.value=p.coords.latitude.toFixed(6);gpLon.value=p.coords.longitude.toFixed(6)},e=>alert(e.message),{enableHighAccuracy:true})}
async function saveGps(){if(!gpLat.value||!gpLon.value)return alert('Koordinaten fehlen.');try{const api=await getCloud();await api.createItemByName('GPSPunkte',{FahrzeugId:String(S.vehicle.id),NutzungId:String(S.usage.cloudId),TagesetappeId:String(S.day.id),Zeitpunkt:new Date().toISOString(),Breite:Number(gpLat.value),Laenge:Number(gpLon.value),Quelle:'Manuell/GPS',Testdaten:testFlag(),Aktiv:true});back()}catch(e){alert(e.message)}}
function media(){head('Foto / Film',S.vehicle.name);app.innerHTML=`<div class="card"><input id="mediaFile" type="file" accept="image/*,video/*" multiple capture="environment"><p class="muted">Im Alpha-Test wird die Datei lokal im Browser vorgemerkt und der Dateiname/Bezug in SharePoint gespeichert. Binäre Cloud-Dateiablage folgt nach dem Phase-1-Praxistest.</p><button class="primary" onclick="saveMediaRefs()">Auswahl übernehmen</button></div>`}
async function saveMediaRefs(){const files=[...mediaFile.files];if(!files.length)return alert('Datei auswählen.');try{const api=await getCloud();for(const f of files){const key='fp-media-'+crypto.randomUUID(),r=new FileReader();r.onload=()=>{try{localStorage.setItem(key,r.result)}catch{}};if(f.size<2_000_000)r.readAsDataURL(f);await api.createItemByName('Medien',{FahrzeugId:String(S.vehicle.id),NutzungId:String(S.usage.cloudId),TagesetappeId:String(S.day.id),BezugTyp:'Nutzung',BezugId:String(S.usage.cloudId),Medientyp:f.type.startsWith('video')?'Video':'Foto',DateiRef:`${f.name}|${key}`,AufgenommenAm:new Date().toISOString(),HinzugefuegtAm:new Date().toISOString(),Testdaten:testFlag(),Aktiv:true})}back()}catch(e){alert(e.message)}}
async function crewchange(){
  head('Besatzung ändern',S.vehicle.name);
  app.innerHTML='<div class="card">Personen werden geladen …</div>';
  try{
    const api=await getCloud(),[people,funcs,current]=await Promise.all([list(api,'Personen'),list(api,'PersonFunktionen'),list(api,'NutzungsPersonen')]);
    const p=profileDef(),active=people.filter(x=>x.fields.Aktiv!==false),
      by=fn=>new Set(funcs.filter(x=>x.fields.Funktion===fn&&x.fields.Aktiv!==false).map(x=>String(x.fields.PersonId))),
      prim=active.filter(x=>by(p.functions[0]).has(String(x.id))),
      sec=active.filter(x=>by(p.functions[1]).has(String(x.id))),
      guests=active.filter(x=>by('Gast').has(String(x.id))),
      now=current.filter(x=>String(x.fields.NutzungId)===String(S.usage.cloudId)&&String(x.fields.TagesetappeId)===String(S.day.id));
    const currentPrimary=now.find(x=>x.fields.Funktion===p.functions[0])?.fields?.PersonId||'';
    const currentSec=new Set(now.filter(x=>x.fields.Funktion===p.functions[1]).map(x=>String(x.fields.PersonId)));
    const currentGuests=new Set(now.filter(x=>x.fields.Funktion==='Gast').map(x=>String(x.fields.PersonId)));
    app.innerHTML=`<div class="card">
      <div class="field"><label>${p.functions[0]}</label><select id="ccPrim" onchange="refreshCrewChangeExclusions()"><option value="">– auswählen –</option>${prim.map(x=>`<option value="${x.id}" ${String(x.id)===String(currentPrimary)?'selected':''}>${esc(x.fields.Anzeigename||x.fields.Title)}</option>`).join('')}</select></div>
      ${personPicker(`${p.functions[1]} · 0 bis X`,sec,'ccsecondary')}
      ${personPicker('Gäste · 0 bis X',guests,'ccguest')}
      <button class="primary" onclick="saveCrewChange102()">Besatzung übernehmen</button>
    </div>`;
    document.querySelectorAll('[data-ccsecondary]').forEach(x=>x.checked=currentSec.has(String(x.dataset.ccsecondary)));
    document.querySelectorAll('[data-ccguest]').forEach(x=>x.checked=currentGuests.has(String(x.dataset.ccguest)));
    refreshCrewChangeExclusions();
  }catch(e){failBox(e,'start')}
}
function refreshCrewChangeExclusions(){
  const primary=document.getElementById('ccPrim')?.value||'';
  document.querySelectorAll('[data-ccsecondary],[data-ccguest]').forEach(cb=>{
    const id=String(cb.dataset.ccsecondary||cb.dataset.ccguest||'');
    cb.disabled=id===String(primary);
    if(cb.disabled) cb.checked=false;
  });
}
async function saveCrewChange102(){
  const p=profileDef(),primary=document.getElementById('ccPrim')?.value||'';
  if(!primary)return alert(`Bitte ${p.functions[0]} auswählen.`);
  try{
    const api=await getCloud(),all=await list(api,'NutzungsPersonen'),
      existing=all.filter(x=>String(x.fields.NutzungId)===String(S.usage.cloudId)&&String(x.fields.TagesetappeId)===String(S.day.id));
    for(const x of existing){ try{ await api.deleteItemByName('NutzungsPersonen',x.id) }catch{} }
    await api.createItemByName('NutzungsPersonen',{NutzungId:String(S.usage.cloudId),TagesetappeId:String(S.day.id),PersonId:primary,Funktion:p.functions[0],Testdaten:testFlag()});
    for(const id of checkedIds('ccsecondary')) await api.createItemByName('NutzungsPersonen',{NutzungId:String(S.usage.cloudId),TagesetappeId:String(S.day.id),PersonId:id,Funktion:p.functions[1],Testdaten:testFlag()});
    for(const id of checkedIds('ccguest')) await api.createItemByName('NutzungsPersonen',{NutzungId:String(S.usage.cloudId),TagesetappeId:String(S.day.id),PersonId:id,Funktion:'Gast',Testdaten:testFlag()});
    back();
  }catch(e){alert(e.message)}
}
async function saveCrewChange(){try{const api=await getCloud(),p=profileDef();if(ccPrim.value)await api.createItemByName('NutzungsPersonen',{NutzungId:String(S.usage.cloudId),TagesetappeId:String(S.day.id),PersonId:ccPrim.value,Funktion:p.functions[0],Testdaten:testFlag()});for(const id of selectedValues(ccSec))await api.createItemByName('NutzungsPersonen',{NutzungId:String(S.usage.cloudId),TagesetappeId:String(S.day.id),PersonId:id,Funktion:p.functions[1],Testdaten:testFlag()});for(const id of selectedValues(ccGuest))await api.createItemByName('NutzungsPersonen',{NutzungId:String(S.usage.cloudId),TagesetappeId:String(S.day.id),PersonId:id,Funktion:'Gast',Testdaten:testFlag()});back()}catch(e){alert(e.message)}}

function dayend(){head('Tagesabschluss',S.vehicle.name);app.innerHTML=`<div class="card"><div class="field"><label>Tatsächlicher Tagesziel-/Aufenthaltsort</label><input id="actual" value="${esc(S.day?.goal||'')}"></div>${endMeters()}<div class="field"><label>Tagesnotiz</label><textarea id="dayNote"></textarea></div><div class="actions"><button class="primary" onclick="finishV1(false)">Tag abschließen</button>${S.usage?.multi?'<button onclick="finishV1(true)">Tag abschließen · Nutzung bleibt aktiv</button>':''}</div></div>`}
async function finishV1(continueUsage=false){try{const api=await getCloud(),now=new Date().toISOString(),vals=[...document.querySelectorAll('[id^=em]')].map(x=>x.value);await api.updateItemByName('Tagesetappen',S.day.id,{TatsaechlichesZiel:actual.value.trim(),Ende:now,Status:'Abgeschlossen'});for(let i=0;i<(S.metrics||[]).length;i++){if(vals[i]==='')continue;const m=S.metrics[i];await api.createItemByName('Messwerte',{FahrzeugId:String(S.vehicle.id),NutzungId:String(S.usage.cloudId),TagesetappeId:String(S.day.id),KomponenteId:m.componentId,Messgroesse:m.measure,Wert:Number(vals[i]),Einheit:m.unit,Phase:'Ende',GemessenAm:now,Quelle:'Manuell',Testdaten:testFlag(),Aktiv:true})}if(dayNote.value.trim())await api.createItemByName('Ereignisse',{FahrzeugId:String(S.vehicle.id),NutzungId:String(S.usage.cloudId),TagesetappeId:String(S.day.id),BenutzerId:'current',Art:'Tagesabschluss',Zeitpunkt:now,Notiz:dayNote.value.trim(),Testdaten:testFlag(),Aktiv:true});if(!continueUsage)await api.updateItemByName('Nutzungen',S.usage.cloudId,{Ende:now,Status:'Beendet'});localStorage.removeItem('fp-current');S.stack=[];S.view='start';render()}catch(e){alert(e.message)}}

async function usageHistory(){head('Nutzungen / Historie','SharePoint-Auswertung');app.innerHTML='<div class="card">Historie wird geladen …</div>';try{const api=await getCloud(),[us,vs,types,days,events,costs]=await Promise.all([list(api,'Nutzungen'),list(api,'Fahrzeuge'),list(api,'Nutzungsarten'),list(api,'Tagesetappen'),list(api,'Ereignisse'),list(api,'Ausgaben')]);const vm=Object.fromEntries(vs.map(x=>[String(x.id),x.fields.Fahrzeugname||x.fields.Title])),tm=Object.fromEntries(types.map(x=>[String(x.id),x.fields.Name||x.fields.Title]));app.innerHTML=`<div class="card"><button onclick="exportPhase1Data()">Kompletten Datenexport erzeugen</button></div>${us.sort((a,b)=>String(b.fields.Beginn||'').localeCompare(String(a.fields.Beginn||''))).map(u=>{const ds=days.filter(d=>String(d.fields.NutzungId)===String(u.id)),es=events.filter(e=>String(e.fields.NutzungId)===String(u.id)),sum=costs.filter(c=>String(c.fields.NutzungId)===String(u.id)).reduce((a,c)=>a+Number(c.fields.Betrag||0),0);return `<div class="card"><b>${esc(vm[String(u.fields.FahrzeugId)]||'Fahrzeug')} · ${esc(tm[String(u.fields.NutzungsartId)]||'Nutzung')}</b><div class="muted">${fmtDate(u.fields.Beginn)} · ${esc(u.fields.Startpunkt||'')} → ${esc(u.fields.GeplantesZiel||u.fields.GeplanterEndort||'')} · ${esc(u.fields.Status||'')}</div><div>${ds.length} Tagesetappe(n) · ${es.length} Ereignis(se) · Kosten ${sum.toFixed(2)} €${u.fields.Testdaten?' · TEST':''}</div></div>`}).join('')||'<div class="card">Noch keine Nutzungen.</div>'}` }catch(e){failBox(e)}}

async function workshop(){head('Werkstatt','Störungen · Wartung · Arbeiten · Aufgaben · Prüfungen');app.innerHTML='<div class="card">Werkstattdaten werden geladen …</div>';try{const api=await getCloud(),[vs,st,wo,wp,tasks,ins]=await Promise.all([list(api,'Fahrzeuge'),list(api,'Stoerungen'),list(api,'Arbeiten'),list(api,'Wartungsplaene'),list(api,'Aufgaben'),list(api,'Pruefungen')]);const vopt=vs.filter(x=>x.fields.Aktiv!==false).map(x=>`<option value="${x.id}">${esc(x.fields.Fahrzeugname||x.fields.Title)}</option>`).join('');const vm=Object.fromEntries(vs.map(x=>[String(x.id),x.fields.Fahrzeugname||x.fields.Title]));app.innerHTML=`<div class="card"><div class="section first">Neue Störung / Aufgabe / Prüfung</div><select id="wkVehicle">${vopt}</select><div class="grid compact"><input id="wkDesc" placeholder="Beschreibung"><select id="wkKind"><option>Störung</option><option>Aufgabe</option><option>Wartungsplan</option><option>Prüfung</option><option>Arbeit / Reparatur</option></select><input id="wkDue" type="date"></div><button class="primary" onclick="addWorkshopEntry()">Eintrag anlegen</button></div><div class="card"><div class="section first">Offene Störungen</div>${st.filter(x=>x.fields.Aktiv!==false).map(x=>`<div class="line"><div><b>${esc(vm[String(x.fields.FahrzeugId)]||'')} · ${esc(x.fields.Kategorie||'Störung')}</b><div>${esc(x.fields.Beschreibung||'')}</div><div class="muted">${esc(x.fields.Status||'Offen')} · ${esc(x.fields.Prioritaet||'')}</div></div>${actionsHtml('Stoerungen',x,'')}</div>`).join('')||'<p class="muted">Keine offenen Störungen.</p>'}</div><div class="card"><div class="section first">Aufgaben / Wartung / Prüfungen / Arbeiten</div>${tasks.map(x=>`<div><b>Aufgabe:</b> ${esc(x.fields.Aufgabe||'')} · ${fmtDate(x.fields.FaelligAm)} · ${esc(x.fields.Status||'')}</div>`).join('')}${wp.map(x=>`<div><b>Wartung:</b> ${esc(x.fields.Name||'')} · ${esc(x.fields.IntervallRegel||'')}</div>`).join('')}${ins.map(x=>`<div><b>Prüfung:</b> ${esc(x.fields.Art||'')} · gültig bis ${fmtDate(x.fields.GueltigBis)}</div>`).join('')}${wo.map(x=>`<div><b>Arbeit:</b> ${esc(x.fields.Arbeitsart||'')} · ${esc(x.fields.Beschreibung||'')}</div>`).join('')}</div>`}catch(e){failBox(e)}}
async function addWorkshopEntry(){if(!wkDesc.value.trim())return alert('Beschreibung eingeben.');try{const api=await getCloud(),f={FahrzeugId:String(wkVehicle.value),Testdaten:testFlag(),Aktiv:true};if(wkKind.value==='Störung')await api.createItemByName('Stoerungen',{...f,Kategorie:'Technik',Beschreibung:wkDesc.value.trim(),GemeldetAm:new Date().toISOString(),Status:'Offen',Prioritaet:'Normal'});else if(wkKind.value==='Aufgabe')await api.createItemByName('Aufgaben',{...f,BezugTyp:'Fahrzeug',BezugId:String(wkVehicle.value),Aufgabe:wkDesc.value.trim(),FaelligAm:isoDate(wkDue.value),Status:'Offen'});else if(wkKind.value==='Wartungsplan')await api.createItemByName('Wartungsplaene',{...f,KomponenteId:'',Name:wkDesc.value.trim(),IntervallRegel:wkDue.value?'Nächster Termin '+wkDue.value:'',Aktiv:true});else if(wkKind.value==='Prüfung')await api.createItemByName('Pruefungen',{...f,Art:wkDesc.value.trim(),GeprueftAm:new Date().toISOString(),GueltigBis:isoDate(wkDue.value),Ergebnis:'Offen'});else await api.createItemByName('Arbeiten',{...f,KomponenteId:'',StoerungId:'',Arbeitsart:'Arbeit',Beschreibung:wkDesc.value.trim(),AbgeschlossenAm:wkDue.value?isoDate(wkDue.value):null,Waehrung:'EUR'});render()}catch(e){alert(e.message)}}

async function lending(){head('Verleihmodus','Fahrzeugüberlassung und Übergabe');app.innerHTML='<div class="card">Verleihdaten werden geladen …</div>';try{const api=await getCloud(),[vs,ps,ls]=await Promise.all([list(api,'Fahrzeuge'),list(api,'Personen'),list(api,'Fahrzeugueberlassungen')]);const vm=Object.fromEntries(vs.map(x=>[String(x.id),x.fields.Fahrzeugname||x.fields.Title])),pm=Object.fromEntries(ps.map(x=>[String(x.id),x.fields.Anzeigename||x.fields.Title]));app.innerHTML=`<div class="card" id="lend"><div class="section first">Neue Überlassung</div><div class="grid compact"><select id="leVehicle">${vs.filter(x=>x.fields.Aktiv!==false).map(x=>`<option value="${x.id}">${esc(x.fields.Fahrzeugname||x.fields.Title)}</option>`).join('')}</select><select id="lePerson">${ps.filter(x=>x.fields.Aktiv!==false).map(x=>`<option value="${x.id}">${esc(x.fields.Anzeigename||x.fields.Title)}</option>`).join('')}</select><input id="leFrom" type="datetime-local"><input id="leTo" type="datetime-local"></div><textarea id="leRights" placeholder="Rechte, z. B. Nutzung starten, Cockpit, keine Konfiguration"></textarea><div class="grid compact"><label class="checkrow"><input id="leLicence" type="checkbox"> Führerschein/Lizenz geprüft</label><label class="checkrow"><input id="leQual" type="checkbox"> Qualifikation geprüft</label></div><textarea id="leNote" placeholder="Übergabenotiz / Zustand / Hinweise"></textarea><button class="primary" onclick="addLending()">Überlassung anlegen</button><div class="section">Vorhandene Überlassungen</div>${ls.map(x=>`<div class="line"><div><b>${esc(vm[String(x.fields.FahrzeugId)]||'')} → ${esc(pm[String(x.fields.LeiherPersonId)]||'')}</b><div class="muted">${fmtDate(x.fields.Beginn)} bis ${fmtDate(x.fields.Ende)} · ${esc(x.fields.Status||'')}</div></div>${actionsHtml('Fahrzeugueberlassungen',x,'lend')}</div>`).join('')||'<p class="muted">Keine Überlassung.</p>'}</div>`}catch(e){failBox(e)}}
async function addLending(){if(!leFrom.value||!leTo.value)return alert('Beginn und Ende eingeben.');try{const api=await getCloud(),now=new Date().toISOString();await api.createItemByName('Fahrzeugueberlassungen',{FahrzeugId:String(leVehicle.value),LeiherPersonId:String(lePerson.value),Beginn:new Date(leFrom.value).toISOString(),Ende:new Date(leTo.value).toISOString(),Rechte:leRights.value.trim(),Status:'Vorbereitet',UebergabeNotiz:leNote.value.trim(),FuehrerscheinGeprueftAm:leLicence.checked?now:null,QualifikationGeprueftAm:leQual.checked?now:null,Testdaten:testFlag(),Aktiv:true});rerenderKeepPosition('lend')}catch(e){alert(e.message)}}

async function exportPhase1Data(){try{const api=await getCloud(),schema=await(await fetch('phase1-sharepoint-schema.json',{cache:'no-store'})).json(),data={exportedAt:new Date().toISOString(),version:VERSION,lists:{}};for(const l of schema.lists){try{data.lists[l.internalName]=await list(api,l.internalName)}catch(e){data.lists[l.internalName]={error:e.message}}}const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`Fahrzeugplattform_Export_${new Date().toISOString().slice(0,10)}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}catch(e){alert(e.message)}}
async function clearTestData(){if(!confirm('Alle als Testdaten markierten Bewegungs-/Vorgangsdaten wirklich löschen? Stammdaten wie Fahrzeuge, Personen, Orte und Komponenten bleiben erhalten.'))return;try{const api=await getCloud(),schema=await(await fetch('phase1-sharepoint-schema.json',{cache:'no-store'})).json(),targets=['NutzungsPersonen','NutzungsTiere','NutzungsZwischenziele','Tagesetappen','Ereignisse','Aufenthalte','GPSPunkte','Messwerte','Versorgungsvorgaenge','Kontrollen','Arbeiten','Aufgaben','Pruefungen','Medien','Dokumente','Ausgaben','Fahrzeugueberlassungen','ReisecheckPunkte','Reisechecks','Stoerungen','Nutzungen'];let count=0;for(const ln of targets){let rows=[];try{rows=await list(api,ln)}catch{}for(const r of rows.filter(x=>x.fields.Testdaten===true)){try{await api.deleteItemByName(ln,r.id);count++}catch{}}}alert(`${count} Testdatensätze gelöscht.`)}catch(e){alert(e.message)}}
function settings(){head('Einstellungen / Daten','Testbetrieb und Export');app.innerHTML=`<div class="card"><div class="section first">Testmodus</div><label class="checkrow"><input id="setTest" type="checkbox" ${testFlag()?'checked':''} onchange="localStorage.setItem(TESTFLAG_KEY,this.checked?'1':'0')"> Neu erzeugte Bewegungs-/Vorgangsdaten als Testdaten markieren</label><p class="muted">Echte Stammdaten bleiben davon unberührt. Testdaten können später gesammelt entfernt werden.</p><button class="danger-lite" onclick="clearTestData()">Alle markierten Testdaten löschen</button></div><div class="card"><div class="section first">Daten</div><button onclick="exportPhase1Data()">Kompletten JSON-Datenexport erzeugen</button></div><div class="grid"><button class="menu" onclick="go('m365setup')"><b>Microsoft 365 Setup</b><span class="muted">SharePoint-Struktur prüfen / ergänzen</span></button></div>`}



