function refreshPeopleExclusions(){
 const primary=document.getElementById('primaryPerson')?.value||'';
 document.querySelectorAll('[data-secondary],[data-guest]').forEach(cb=>{
   cb.disabled=String(cb.dataset.secondary||cb.dataset.guest)===String(primary);
   if(cb.disabled)cb.checked=false;
 });
}
function checkedIds(attr){return [...document.querySelectorAll(`[data-${attr}]:checked`)].map(x=>x.getAttribute(`data-${attr}`))}
async function setupBase(){let p=profileDef();head('Startangaben',`${S.vehicle.name} · ${S.usage.name}`);app.innerHTML='<div class="card">Stammdaten werden geladen …</div>';try{
 const api=await getCloud(),[persons,funcs,orts,sites,animals]=await Promise.all([list(api,'Personen'),list(api,'PersonFunktionen'),list(api,'Orte'),list(api,'Standorte'),list(api,'Tiere')]);S.locationData={orts,sites};
 const active=persons.filter(x=>x.fields.Aktiv!==false),idsFor=fn=>new Set(funcs.filter(x=>x.fields.Funktion===fn&&x.fields.Aktiv!==false).map(x=>String(x.fields.PersonId))),primary=p.functions[0],secondary=p.functions[1],primIds=idsFor(primary),secIds=idsFor(secondary),guestIds=idsFor('Gast'),prim=active.filter(x=>primIds.has(String(x.id))),sec=active.filter(x=>secIds.has(String(x.id))),guests=active.filter(x=>guestIds.has(String(x.id))),multi=S.usage.multi;
 app.innerHTML=`<div class="card">${multi?`<div class="section first">Gesamtplanung ${esc(S.usage.name)}</div><div class="grid compact"><div class="field"><label>Geplanter Start *</label><input id="planFrom" type="date"></div><div class="field"><label>Geplantes Ende *</label><input id="planTo" type="date"></div></div>${locSelect('planStart','Geplanter Startort',orts,sites)}${locSelect('planEnd','Geplanter Endort',orts,sites)}<div class="section">Geplante Zwischenziele</div>${locSelect('stop','Zwischenziel auswählen',orts,sites)}<button type="button" onclick="addPlannedStop()">Zwischenziel hinzufügen</button><div id="plannedStops"></div><hr>`:''}<div class="section first">${multi?'Heutige Tagesetappe':'Nutzung'}</div>${locSelect('dayStart','Startpunkt',orts,sites)}${locSelect('dayGoal',multi?'Heutiges Tagesziel':'Geplantes Ziel (optional)',orts,sites)}
 <div class="section">Personen</div><div class="field"><label>${primary} · genau eine Person</label><select id="primaryPerson" onchange="refreshPeopleExclusions()"><option value="">– auswählen –</option>${prim.map(x=>`<option value="${x.id}">${esc(x.fields.Anzeigename||x.fields.Title)}</option>`).join('')}</select></div>${personPicker(`${secondary} · 0 bis X`,sec,'secondary')}${personPicker('Gäste · 0 bis X',guests,'guest')}
 <div class="section">Tiere auf dieser Reise / Nutzung</div>${animals.filter(x=>x.fields.Aktiv!==false).map(x=>`<label class="person-tile"><input type="checkbox" data-animal="${x.id}"> <span>${esc(x.fields.Name||x.fields.Title)} · ${esc(x.fields.Tierart||'')}</span></label>`).join('')||'<p class="muted">Keine Tiere im Tierstamm.</p>'}
 <div class="section">Tages-Anfangsstand</div>${startMeters()}<button class="primary" onclick="beginCloud101()">Nutzung starten</button></div>`;
 ['planStart','planEnd','stop','dayStart','dayGoal'].forEach(refreshSiteOptions);refreshPeopleExclusions();
}catch(e){failBox(e)}}
async function beginCloud101(){
 const pp=document.getElementById('primaryPerson');if(!pp||!pp.value)return alert(`Bitte ${profileDef().functions[0]} auswählen.`);
 if(S.usage.multi&&(!document.getElementById('planFrom')?.value||!document.getElementById('planTo')?.value))return alert('Geplanten Start und geplantes Ende eingeben.');
 try{
  const api=await getCloud(),now=new Date().toISOString(),multi=S.usage.multi,orts=S.locationData?.orts||[],sites=S.locationData?.sites||[],ds=locValue('dayStart',orts,sites),dg=locValue('dayGoal',orts,sites),ps=multi?locValue('planStart',orts,sites):{ortId:'',standortId:'',text:''},pe=multi?locValue('planEnd',orts,sites):{ortId:'',standortId:'',text:''};
  const fields={Title:`${S.vehicle.name} · ${S.usage.name}`,FahrzeugId:String(S.vehicle.id),BenutzerId:'current',NutzungsartId:String(S.usage.id),Beginn:now,Status:'Aktiv',Startpunkt:ds.text,GeplantesZiel:dg.text,Testdaten:testFlag()};
  if(multi){fields.GeplanterBeginn=new Date(planFrom.value+'T12:00:00').toISOString();fields.GeplantesEndeDatum=new Date(planTo.value+'T12:00:00').toISOString();fields.GeplanterStartort=ps.text;fields.GeplanterEndort=pe.text;fields.GeplanterStartOrtId=ps.ortId;fields.GeplanterStartStandortId=ps.standortId;fields.GeplanterEndOrtId=pe.ortId;fields.GeplanterEndStandortId=pe.standortId}
  const u=await api.createItemByName('Nutzungen',fields);
  const day=await api.createItemByName('Tagesetappen',{NutzungId:String(u.id),FahrzeugId:String(S.vehicle.id),TagNr:1,Datum:now,Startpunkt:ds.text,Tagesziel:dg.text,Beginn:now,Status:'Aktiv',StartOrtId:ds.ortId,StartStandortId:ds.standortId,ZielOrtId:dg.ortId,ZielStandortId:dg.standortId,Testdaten:testFlag()});
  if(multi){const stops=[...document.querySelectorAll('.planned-stop')];for(let i=0;i<stops.length;i++){const d=stops[i],o=orts.find(x=>String(x.id)===String(d.dataset.ortId)),s=sites.find(x=>String(x.id)===String(d.dataset.standortId));await api.createItemByName('NutzungsZwischenziele',{NutzungId:String(u.id),Sortierung:i+1,Ort:s?.fields?.Name||o?.fields?.Name||'',OrtId:d.dataset.ortId||'',StandortId:d.dataset.standortId||'',Testdaten:testFlag()})}}
  await api.createItemByName('NutzungsPersonen',{NutzungId:String(u.id),TagesetappeId:String(day.id),PersonId:pp.value,Funktion:profileDef().functions[0],Testdaten:testFlag()});
  for(const id of checkedIds('secondary'))await api.createItemByName('NutzungsPersonen',{NutzungId:String(u.id),TagesetappeId:String(day.id),PersonId:id,Funktion:profileDef().functions[1],Testdaten:testFlag()});
  for(const id of checkedIds('guest'))await api.createItemByName('NutzungsPersonen',{NutzungId:String(u.id),TagesetappeId:String(day.id),PersonId:id,Funktion:'Gast',Testdaten:testFlag()});
  for(const id of checkedIds('animal'))await api.createItemByName('NutzungsTiere',{NutzungId:String(u.id),TierId:id,Testdaten:testFlag()});
  S.usage.cloudId=String(u.id);S.day={id:String(day.id),start:ds.text,goal:dg.text,startMeters:[...document.querySelectorAll('[id^=sm]')].map(x=>x.value)};localStorage.setItem('fp-current',JSON.stringify({vehicle:S.vehicle,usage:S.usage,day:S.day,startedAt:now}));
  await saveStartMetrics101(api);go('cockpit');
 }catch(e){alert('Nutzung konnte nicht gestartet werden: '+e.message)}
}
async function saveStartMetrics101(api){const vals=S.day?.startMeters||[];for(let i=0;i<(S.metrics||[]).length;i++){if(vals[i]===''||vals[i]==null)continue;const m=S.metrics[i];try{await api.createItemByName('Messwerte',{FahrzeugId:String(S.vehicle.id),NutzungId:String(S.usage.cloudId),TagesetappeId:String(S.day.id),KomponenteId:m.componentId,Messgroesse:m.measure,Wert:Number(vals[i]),Einheit:m.unit,Phase:'Start',GemessenAm:new Date().toISOString(),Quelle:'Manuell',Testdaten:testFlag(),Aktiv:true})}catch(e){console.warn(e)}}}
async function beginCloud(){return beginCloud101()}

function daysUntil(v){if(!v)return null;const a=new Date();a.setHours(0,0,0,0);const b=new Date(v);b.setHours(0,0,0,0);return Math.ceil((b-a)/86400000)}
function dueText(d){if(d===null)return'';if(d<0)return`${Math.abs(d)} Tag(e) überfällig`;if(d===0)return'heute fällig';return`in ${d} Tag(en)`}
async function cockpit(){const p=profileDef();head('Cockpit',`${S.vehicle.name} · ${S.usage.name}`);let due=[];try{const api=await getCloud(),[fp,cs,wp]=await Promise.all([list(api,'FahrzeugPruefpunkte'),list(api,'Komponenten'),list(api,'Wartungsplaene')]);fp.filter(x=>String(x.fields.FahrzeugId)===String(S.vehicle.id)&&x.fields.Aktiv!==false&&x.fields.NaechstePruefung).forEach(x=>due.push({name:x.fields.Name,source:'Fahrzeugprüfung',days:daysUntil(x.fields.NaechstePruefung)}));cs.filter(x=>String(x.fields.FahrzeugId)===String(S.vehicle.id)&&x.fields.Aktiv!==false&&x.fields.Pruefpflicht&&x.fields.NaechstePruefung).forEach(x=>due.push({name:x.fields.Name,source:'Komponente',days:daysUntil(x.fields.NaechstePruefung)}));wp.filter(x=>String(x.fields.FahrzeugId)===String(S.vehicle.id)&&x.fields.Aktiv!==false&&x.fields.NaechsterTermin).forEach(x=>due.push({name:x.fields.Name,source:'Werkstatt / Service',days:daysUntil(x.fields.NaechsterTermin)}));}catch{}
 due=due.filter(x=>x.days!==null&&x.days<=60).sort((a,b)=>a.days-b.days);
 app.innerHTML=`${due.length?`<div class="card due-card"><div class="section first">Fälligkeiten</div>${due.map(x=>`<div class="due-line"><b>${esc(x.name)}</b><span>${esc(x.source)} · ${dueText(x.days)}</span></div>`).join('')}</div>`:''}<div class="cockpit"><button onclick="go('control')">Kontrolle</button><button onclick="quickMovementEvent()">${S.vehicle.profile==='motorboat'?'Ablegen':'Abfahrt'}</button><button onclick="go('event')">Ereignis</button><button onclick="go('stay')">${S.vehicle.profile==='motorboat'?'Anlegen / Ankern':'Ankunft / Aufenthalt'}</button></div><div class="secondary"><button onclick="go('supply')">Tanken / Versorgung</button><button onclick="go('measure')">Messwert / Füllstand</button><button onclick="go('gps')">GPS-Punkt</button><button onclick="go('media')">Foto / Film</button><button onclick="go('crewchange')">Besatzung ändern</button><button onclick="go('dayend')">Tagesabschluss</button></div>`;
}

async function usageHistory(){head('Planung & Historie','Geplante · aktive · abgeschlossene Nutzungen');app.innerHTML='<div class="card">Nutzungen werden geladen …</div>';try{const api=await getCloud(),[us,vs,types,days,events,costs]=await Promise.all([list(api,'Nutzungen'),list(api,'Fahrzeuge'),list(api,'Nutzungsarten'),list(api,'Tagesetappen'),list(api,'Ereignisse'),list(api,'Ausgaben')]);const vm=Object.fromEntries(vs.map(x=>[String(x.id),x.fields.Fahrzeugname||x.fields.Title])),tm=Object.fromEntries(types.map(x=>[String(x.id),x.fields.Name||x.fields.Title]));app.innerHTML=`<div class="card"><button onclick="exportPhase1Data()">Kompletten Datenexport erzeugen</button></div>${us.sort((a,b)=>String(b.fields.GeplanterBeginn||b.fields.Beginn||'').localeCompare(String(a.fields.GeplanterBeginn||a.fields.Beginn||''))).map(u=>{const ds=days.filter(d=>String(d.fields.NutzungId)===String(u.id)),es=events.filter(e=>String(e.fields.NutzungId)===String(u.id)),sum=costs.filter(c=>String(c.fields.NutzungId)===String(u.id)).reduce((a,c)=>a+Number(c.fields.Betrag||0),0);return `<button class="menu usage-card" onclick="S.usageDetailId='${u.id}';go('usageDetail')"><b>${esc(vm[String(u.fields.FahrzeugId)]||'Fahrzeug')} · ${esc(tm[String(u.fields.NutzungsartId)]||'Nutzung')}</b><span class="muted">${fmtDate(u.fields.GeplanterBeginn||u.fields.Beginn)} · ${esc(u.fields.Startpunkt||u.fields.GeplanterStartort||'')} → ${esc(u.fields.GeplantesZiel||u.fields.GeplanterEndort||'')} · ${esc(u.fields.Status||'Geplant')}</span><span>${ds.length} Tagesetappe(n) · ${es.length} Ereignis(se) · Kosten ${sum.toFixed(2)} €${u.fields.Testdaten?' · TEST':''}</span></button>`}).join('')||'<div class="card">Noch keine Nutzungen.</div>'}` }catch(e){failBox(e)}}
async function usageDetail(){head('Nutzung','Planung · Tagesetappen · Fortsetzen · Nachtragen');app.innerHTML='<div class="card">Nutzung wird geladen …</div>';try{const api=await getCloud(),u=await api.getItemByName('Nutzungen',S.usageDetailId),[vs,types,days,ps,np,animals,na]=await Promise.all([list(api,'Fahrzeuge'),list(api,'Nutzungsarten'),list(api,'Tagesetappen'),list(api,'Personen'),list(api,'NutzungsPersonen'),list(api,'Tiere'),list(api,'NutzungsTiere')]);const v=vs.find(x=>String(x.id)===String(u.fields.FahrzeugId)),t=types.find(x=>String(x.id)===String(u.fields.NutzungsartId)),ds=days.filter(x=>String(x.fields.NutzungId)===String(u.id)).sort((a,b)=>Number(a.fields.TagNr||0)-Number(b.fields.TagNr||0)),pm=Object.fromEntries(ps.map(x=>[String(x.id),x.fields.Anzeigename||x.fields.Title])),am=Object.fromEntries(animals.map(x=>[String(x.id),x.fields.Name||x.fields.Title])),people=np.filter(x=>String(x.fields.NutzungId)===String(u.id)),pets=na.filter(x=>String(x.fields.NutzungId)===String(u.id));
 app.innerHTML=`<div class="card"><b>${esc(v?.fields?.Fahrzeugname||'Fahrzeug')} · ${esc(t?.fields?.Name||'Nutzung')}</b><div class="muted">Status: ${esc(u.fields.Status||'Geplant')}</div><div>${esc(u.fields.GeplanterStartort||u.fields.Startpunkt||'')} → ${esc(u.fields.GeplanterEndort||u.fields.GeplantesZiel||'')}</div><div class="chips">${people.map(x=>`<span>${esc(x.fields.Funktion)}: ${esc(pm[String(x.fields.PersonId)]||'')}</span>`).join('')}${pets.map(x=>`<span>Tier: ${esc(am[String(x.fields.TierId)]||'')}</span>`).join('')}</div><div class="actions">${u.fields.Status==='Geplant'?`<button class="primary" onclick="startPlannedUsage('${u.id}')">Starten</button>`:''}${u.fields.Status==='Aktiv'?`<button class="primary" onclick="continueUsage('${u.id}')">Fortsetzen / neue Tagesetappe</button><button onclick="endWholeUsage('${u.id}')">Gesamtnutzung beenden</button>`:''}</div></div>
 <div class="card"><div class="section first">Tagesetappen</div>${ds.map(d=>`<div class="entitybox"><div class="line"><div><b>Tag ${d.fields.TagNr||'?'} · ${fmtDate(d.fields.Datum)}</b><div class="muted">${esc(d.fields.Startpunkt||'')} → ${esc(d.fields.Tagesziel||d.fields.TatsaechlichesZiel||'')} · ${esc(d.fields.Status||'')}</div></div><button onclick="editDay('${d.id}')">Bearbeiten / nachtragen</button></div>${d.fields.Tagesbericht?`<p>${esc(d.fields.Tagesbericht)}</p>`:''}</div>`).join('')||'<p class="muted">Noch keine Tagesetappe.</p>'}</div>`}catch(e){failBox(e)}}
async function editDay(id){try{const api=await getCloud(),d=await api.getItemByName('Tagesetappen',id);const txt=prompt('Tagesbericht / Freitext ergänzen oder korrigieren:',d.fields.Tagesbericht||'');if(txt===null)return;await api.updateItemByName('Tagesetappen',id,{Tagesbericht:txt,NachgetragenAm:new Date().toISOString()});render()}catch(e){alert(e.message)}}
async function continueUsage(id){try{const api=await getCloud(),u=await api.getItemByName('Nutzungen',id),[vs,types,days]=await Promise.all([list(api,'Fahrzeuge'),list(api,'Nutzungsarten'),list(api,'Tagesetappen')]),v=vs.find(x=>String(x.id)===String(u.fields.FahrzeugId)),t=types.find(x=>String(x.id)===String(u.fields.NutzungsartId)),ds=days.filter(x=>String(x.fields.NutzungId)===String(id)),n=ds.length+1;S.vehicle={id:String(v.id),name:v.fields.Fahrzeugname||v.fields.Title,profile:normalizeProfile(v.fields.Profil||'Motorboot')};S.usage={id:String(t?.id||u.fields.NutzungsartId),name:t?.fields?.Name||'Nutzung',cloudId:String(id),multi:true};await loadVehicleMetrics();const start=prompt(`Startpunkt für Tag ${n}:`,ds.length?(ds[ds.length-1].fields.TatsaechlichesZiel||ds[ds.length-1].fields.Tagesziel||''):'')||'',goal=prompt(`Tagesziel für Tag ${n}:`,'')||'';const day=await api.createItemByName('Tagesetappen',{NutzungId:String(id),FahrzeugId:String(v.id),TagNr:n,Datum:new Date().toISOString(),Startpunkt:start,Tagesziel:goal,Beginn:new Date().toISOString(),Status:'Aktiv',Testdaten:testFlag()});S.day={id:String(day.id),start,goal,startMeters:[]};localStorage.setItem('fp-current',JSON.stringify({vehicle:S.vehicle,usage:S.usage,day:S.day,startedAt:new Date().toISOString()}));go('cockpit')}catch(e){alert(e.message)}}
async function startPlannedUsage(id){try{const api=await getCloud();await api.updateItemByName('Nutzungen',id,{Status:'Aktiv',Beginn:new Date().toISOString(),GeaendertAm:new Date().toISOString()});return continueUsage(id)}catch(e){alert(e.message)}}
async function endWholeUsage(id){if(!confirm('Gesamte Nutzung / Reise wirklich beenden?'))return;try{const api=await getCloud();await api.updateItemByName('Nutzungen',id,{Status:'Beendet',Ende:new Date().toISOString(),GeaendertAm:new Date().toISOString()});render()}catch(e){alert(e.message)}}

async function travelcheck(){head('Reisecheck','Fahrzeug + Personen + Tiere + Gebiet · keine rechtsverbindliche Auskunft');app.innerHTML='<div class="card">Stammdaten werden geladen …</div>';try{const api=await getCloud(),[vs,ps,gs,as]=await Promise.all([list(api,'Fahrzeuge'),list(api,'Personen'),list(api,'Gebiete'),list(api,'Tiere')]);app.innerHTML=`<div class="card"><div class="field"><label>Fahrzeug</label><select id="tcVehicle">${vs.filter(x=>x.fields.Aktiv!==false).map(v=>`<option value="${v.id}">${esc(v.fields.Fahrzeugname||v.fields.Title)}</option>`).join('')}</select></div><div class="section">Mitreisende Personen</div>${ps.filter(x=>x.fields.Aktiv!==false).map(p=>`<label class="person-tile"><input type="checkbox" data-tcperson="${p.id}"> ${esc(p.fields.Anzeigename||p.fields.Title)}</label>`).join('')}<div class="section">Mitreisende Tiere</div>${as.filter(x=>x.fields.Aktiv!==false).map(a=>`<label class="person-tile"><input type="checkbox" data-tcanimal="${a.id}"> ${esc(a.fields.Name||a.fields.Title)} · ${esc(a.fields.Tierart||'')}</label>`).join('')||'<p class="muted">Keine Tiere.</p>'}<div class="field"><label>Gebiet / Revier</label><select id="tcArea">${gs.map(g=>`<option value="${g.id}">${esc(g.fields.Name||g.fields.Title)}</option>`).join('')}</select></div><button class="primary" onclick="runTravelCheck101()">Check erstellen</button></div><div id="tcResult"></div><div class="card"><b>Hinweis</b><p>Diese Prüfung dient als Planungshilfe und ist keine rechtsverbindliche Auskunft. Anforderungen sind vor Reiseantritt anhand aktueller geeigneter Quellen zu prüfen.</p></div>`}catch(e){failBox(e)}}
async function runTravelCheck101(){const people=checkedIds('tcperson'),pets=checkedIds('tcanimal');tcResult.innerHTML=`<div class="card status-warn"><b>Reisecheck vorbereitet</b><p>${people.length} Person(en), ${pets.length} Tier(e) und das gewählte Fahrzeug werden gegen die Anforderungen des Gebiets geprüft. Die Detailprüfung wird aus den hinterlegten Personen-, Tier- und Fahrzeugnachweisen aufgebaut.</p></div>`}

async function lending(){head('Verleihmodus','Fahrzeugüberlassung an variable Personengruppe');app.innerHTML='<div class="card">Verleihdaten werden geladen …</div>';try{const api=await getCloud(),[vs,ps,fs,qs,ls,ups,animals]=await Promise.all([list(api,'Fahrzeuge'),list(api,'Personen'),list(api,'PersonFunktionen'),list(api,'Befaehigungen'),list(api,'Fahrzeugueberlassungen'),list(api,'UeberlassungsPersonen'),list(api,'Tiere')]);S.lendData={vs,ps,fs,qs,animals};const vm=Object.fromEntries(vs.map(x=>[String(x.id),x.fields.Fahrzeugname||x.fields.Title])),pm=Object.fromEntries(ps.map(x=>[String(x.id),x.fields.Anzeigename||x.fields.Title]));app.innerHTML=`<div class="card" id="lend"><div class="section first">Neue Überlassung</div><div class="field"><label>Fahrzeug</label><select id="leVehicle" onchange="renderLendingPeople()">${vs.filter(x=>x.fields.Aktiv!==false).map(x=>`<option value="${x.id}">${esc(x.fields.Fahrzeugname||x.fields.Title)}</option>`).join('')}</select></div><div class="grid compact"><div class="field"><label>Beginn</label><input id="leFrom" type="datetime-local"></div><div class="field"><label>Ende</label><input id="leTo" type="datetime-local"></div></div><div class="section">Personengruppe</div><div id="lendPeople"></div><div class="section">Tiere in dieser Überlassung</div>${animals.filter(x=>x.fields.Aktiv!==false).map(a=>`<label class="person-tile"><input type="checkbox" data-lendanimal="${a.id}"> ${esc(a.fields.Name||a.fields.Title)}</label>`).join('')||'<p class="muted">Keine Tiere.</p>'}<div class="section">App-Rechte für die Gruppe</div>${['Nutzung starten / fortsetzen','Cockpit bedienen','Messwerte / Versorgung erfassen','Kontrollen durchführen','Fotos / Medien hinzufügen','Dokumente ansehen','Kosten ansehen'].map((r,i)=>`<label class="person-tile"><input type="checkbox" data-lendright="${r}" ${i<5?'checked':''}> ${r}</label>`).join('')}<textarea id="leNote" placeholder="Übergabenotiz / Zustand / Hinweise"></textarea><button class="primary" onclick="addLending101()">Überlassung anlegen</button><div class="section">Vorhandene Überlassungen</div>${ls.map(x=>{const members=ups.filter(p=>String(p.fields.UeberlassungId)===String(x.id)&&p.fields.Aktiv!==false);return `<div class="line"><div><b>${esc(vm[String(x.fields.FahrzeugId)]||'')}</b><div>${members.map(m=>esc(pm[String(m.fields.PersonId)]||'')).join(', ')||esc(pm[String(x.fields.LeiherPersonId)]||'')}</div><div class="muted">${fmtDate(x.fields.Beginn)} bis ${fmtDate(x.fields.Ende)} · ${esc(x.fields.Status||'')}</div></div>${actionsHtml('Fahrzeugueberlassungen',x,'lend')}</div>`}).join('')||'<p class="muted">Keine Überlassung.</p>'}</div>`;renderLendingPeople()}catch(e){failBox(e)}}
function renderLendingPeople(){const d=S.lendData;if(!d||!lendPeople)return;const v=d.vs.find(x=>String(x.id)===String(leVehicle.value)),boat=(v?.fields?.Profil||'')==='Motorboot';lendPeople.innerHTML=d.ps.filter(x=>x.fields.Aktiv!==false).map(p=>{const fns=d.fs.filter(f=>String(f.fields.PersonId)===String(p.id)&&f.fields.Aktiv!==false).map(f=>f.fields.Funktion),qual=d.qs.filter(q=>String(q.fields.PersonId)===String(p.id)&&q.fields.Vorhanden!==false),canDrive=boat?fns.includes('Skipper')&&qual.some(q=>/SBF|Boot|Patent/i.test(q.fields.Art||'')):fns.includes('Fahrer')&&qual.some(q=>/Führerschein|Klasse B|BE|C1|C|CE/i.test(q.fields.Art||''));return `<div class="lend-person"><label class="person-tile"><input type="checkbox" data-lendperson="${p.id}"> <b>${esc(p.fields.Anzeigename||p.fields.Title)}</b></label><div class="muted">${canDrive?(boat?'Skipper theoretisch zulässig':'Fahrer theoretisch zulässig'):(boat?'kein nachgewiesenes Skipperrecht':'kein nachgewiesenes Fahrerrecht')}</div><select data-lendfunction="${p.id}"><option>Gast</option><option>${boat?'Crew':'Beifahrer'}</option>${canDrive?`<option>${boat?'Skipper':'Fahrer'}</option>`:''}</select></div>`}).join('')}
async function addLending101(){const members=checkedIds('lendperson');if(!members.length)return alert('Mindestens eine Person auswählen.');if(!leFrom.value||!leTo.value)return alert('Beginn und Ende eingeben.');try{const api=await getCloud(),rights=[...document.querySelectorAll('[data-lendright]:checked')].map(x=>x.dataset.lendright),animalIds=checkedIds('lendanimal'),x=await api.createItemByName('Fahrzeugueberlassungen',{FahrzeugId:String(leVehicle.value),LeiherPersonId:members[0],Beginn:new Date(leFrom.value).toISOString(),Ende:new Date(leTo.value).toISOString(),Rechte:rights.join('|'),Status:'Vorbereitet',UebergabeNotiz:leNote.value.trim(),Gruppenmodus:true,TierIds:animalIds.join('|'),Testdaten:testFlag(),Aktiv:true});for(const id of members){const sel=document.querySelector(`[data-lendfunction="${id}"]`);await api.createItemByName('UeberlassungsPersonen',{UeberlassungId:String(x.id),PersonId:id,Funktion:sel?.value||'Gast',Rechte:rights.join('|'),QualifikationStatus:'automatisch geprüft',Aktiv:true,Testdaten:testFlag()})}rerenderKeepPosition('lend')}catch(e){alert(e.message)}}


